import { randomBytes } from 'node:crypto';

// Document ids are UUIDv7 strings: globally unique, generated by the API (no round trip), and
// time-ordered, so sorting by _id is sorting by creation time and B-tree inserts stay at the
// "right edge" of the index (no random page splits, unlike UUIDv4).

let lastMs = 0;
let seq = 0;

export function uuidv7(): string {
  let ms = Date.now();
  if (ms <= lastMs) {
    // Same millisecond (or clock moved back): keep ids strictly increasing with a sequence.
    seq = (seq + 1) & 0xfff;
    if (seq === 0) lastMs += 1;
    ms = lastMs;
  } else {
    seq = randomBytes(2).readUInt16BE(0) & 0x3ff;
    lastMs = ms;
  }
  const bytes = randomBytes(16);
  bytes.writeUIntBE(ms, 0, 6);
  bytes[6] = 0x70 | ((seq >> 8) & 0x0f); // version 7 + high bits of the sequence
  bytes[7] = seq & 0xff;
  bytes[8] = 0x80 | (bytes[8]! & 0x3f); // RFC 4122 variant
  const hex = bytes.toString('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

export const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Id for one-per-pair documents (a follow, a like, a membership), so duplicates are impossible. */
export const pairId = (...parts: string[]) => parts.join(':');
